style.css:
@-moz-document domain("youtube.com") {
/* GLOW RIOT - RAINBOW VIDEO TITLES ONLY */

@keyframes glow-riot-rainbow {
  0% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000, 0 0 14px #ff0000;
    animation-timing-function: steps(1, end);
  }

  12.5% {
    color: #ff8000;
    text-shadow: 0 0 8px #ff8000, 0 0 14px #ff8000;
    animation-timing-function: steps(1, end);
  }

  25% {
    color: #ffff00;
    text-shadow: 0 0 8px #ffff00, 0 0 14px #ffff00;
    animation-timing-function: steps(1, end);
  }

  37.5% {
    color: #39ff14;
    text-shadow: 0 0 8px #39ff14, 0 0 14px #39ff14;
    animation-timing-function: steps(1, end);
  }

  50% {
    color: #00ffcc;
    text-shadow: 0 0 8px #00ffcc, 0 0 14px #00ffcc;
    animation-timing-function: steps(1, end);
  }

  62.5% {
    color: #008cff;
    text-shadow: 0 0 8px #008cff, 0 0 14px #008cff;
    animation-timing-function: steps(1, end);
  }

  75% {
    color: #a020f0;
    text-shadow: 0 0 8px #a020f0, 0 0 14px #a020f0;
    animation-timing-function: steps(1, end);
  }

  87.5% {
    color: #ff1493;
    text-shadow: 0 0 8px #ff1493, 0 0 14px #ff1493;
    animation-timing-function: steps(1, end);
  }

  100% {
    color: #ff0000;
    text-shadow: 0 0 8px #ff0000, 0 0 14px #ff0000;
  }
}

/* YouTube homepage video titles */

ytd-rich-grid-media #video-title,
ytd-rich-grid-media #video-title-link,
ytd-rich-item-renderer #video-title,
ytd-rich-item-renderer #video-title-link {
  animation-name: glow-riot-rainbow !important;
  animation-duration: 8s !important;
  animation-iteration-count: infinite !important;
  animation-timing-function: steps(1, end) !important;
}
}
